class SolveOptionsDto {
  final double fovEstimateDeg;
  final double? fovMaxErrorDeg;
  final CameraParamsDto? camera;
  final F32Array4? attitudeHintWxyz;
  final double hintUncertaintyDeg;
  final bool strictHint;
  final ExtractionProfileDto profile;
  final bool retryAlternateProfile;

  /// Ladders only: after the staged search fails, search every rung exhaustively.
  /// Off by default so frames without stars fail in about two seconds.
  final bool thorough;
  final double matchThreshold;
  final BigInt? timeoutMs;

  /// Observation time (Unix ms), reported back as `observationUnixMs` for the solar-system
  /// layer; it does not change the solution
  final PlatformInt64? observationUnixMs;

  /// Ladders only: EXIF FocalLengthIn35mmFilm read by the app, for formats the engine does
  /// not decode (HEIC: decode with the platform and use `solveFrameAuto`). Its FOV is tried
  /// first as a hint (±15%) and the ladder still follows; ignored with a camera or a
  /// tracking hint. Files read their own EXIF.
  final double? focalLength35Mm;

  const SolveOptionsDto({
    required this.fovEstimateDeg,
    this.fovMaxErrorDeg,
    this.camera,
    this.attitudeHintWxyz,
    required this.hintUncertaintyDeg,
    required this.strictHint,
    required this.profile,
    required this.retryAlternateProfile,
    required this.thorough,
    required this.matchThreshold,
    this.timeoutMs,
    this.observationUnixMs,
    this.focalLength35Mm,
  });

  /// Defaults shared with core::SolveOptions::new (PhoneJpeg, built-in σ, 5 s timeout)
  static SolveOptionsDto defaults({required double fovEstimateDeg}) => RustLib
      .instance
      .api
      .crateApiTypesSolveOptionsDtoDefaults(fovEstimateDeg: fovEstimateDeg);

  @override
  int get hashCode =>
      fovEstimateDeg.hashCode ^
      fovMaxErrorDeg.hashCode ^
      camera.hashCode ^
      attitudeHintWxyz.hashCode ^
      hintUncertaintyDeg.hashCode ^
      strictHint.hashCode ^
      profile.hashCode ^
      retryAlternateProfile.hashCode ^
      thorough.hashCode ^
      matchThreshold.hashCode ^
      timeoutMs.hashCode ^
      observationUnixMs.hashCode ^
      focalLength35Mm.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SolveOptionsDto &&
          runtimeType == other.runtimeType &&
          fovEstimateDeg == other.fovEstimateDeg &&
          fovMaxErrorDeg == other.fovMaxErrorDeg &&
          camera == other.camera &&
          attitudeHintWxyz == other.attitudeHintWxyz &&
          hintUncertaintyDeg == other.hintUncertaintyDeg &&
          strictHint == other.strictHint &&
          profile == other.profile &&
          retryAlternateProfile == other.retryAlternateProfile &&
          thorough == other.thorough &&
          matchThreshold == other.matchThreshold &&
          timeoutMs == other.timeoutMs &&
          observationUnixMs == other.observationUnixMs &&
          focalLength35Mm == other.focalLength35Mm;
}

class SolveOutcomeDto {
  final SolveStatusDto status;
  final SolvedGeometryDto? solution;
  final List<CentroidDto> centroids;
  final TimingDto timing;
  final bool extractionRetried;

  /// Star-shape diagnostic: median elongation of the brightest quarter (1.0 = round).
  /// **Relative, with no cross-device threshold**: it varies with pixel scale, PSF and
  /// exposure. Round stars on a telescope camera measure 1.3–1.4 and its untracked 3 s
  /// frames 1.8–1.9, while solvable phone frames span 1.13–2.51. Compare against a baseline
  /// from the same camera; never hard-code a threshold.
  final double? medianElongation;

  /// Observation time the solve used (Unix ms, UTC): the options', or for file entries the
  /// header's when it pins the zone (FITS DATE-OBS, EXIF with an offset). Pass it to
  /// `AnnotateOptionsDto.observationUnixMs` for the solar-system layer; null when neither
  /// gave one.
  final PlatformInt64? observationUnixMs;

  /// Where the photo was taken, for file entries whose EXIF has a GPS position. Pass it to
  /// `AnnotateOptionsDto.observer` with the time (the moon's parallax reaches 1° without
  /// it); null for frames and files without a position.
  final ObserverDto? observer;

  const SolveOutcomeDto({
    required this.status,
    this.solution,
    required this.centroids,
    required this.timing,
    required this.extractionRetried,
    this.medianElongation,
    this.observationUnixMs,
    this.observer,
  });

  @override
  int get hashCode =>
      status.hashCode ^
      solution.hashCode ^
      centroids.hashCode ^
      timing.hashCode ^
      extractionRetried.hashCode ^
      medianElongation.hashCode ^
      observationUnixMs.hashCode ^
      observer.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SolveOutcomeDto &&
          runtimeType == other.runtimeType &&
          status == other.status &&
          solution == other.solution &&
          centroids == other.centroids &&
          timing == other.timing &&
          extractionRetried == other.extractionRetried &&
          medianElongation == other.medianElongation &&
          observationUnixMs == other.observationUnixMs &&
          observer == other.observer;
}

